import{b as a,O as t,g as s,j as l}from"./chunks/framework.DcaUmd3X.js";const r="/assets/image-3.DNB5TN1w.webp",i="/assets/image-4.C0EF6914.webp",b=JSON.parse('{"title":"分支策略","description":"","frontmatter":{},"headers":[],"relativePath":"git/branch/branch-strategy/index.md","filePath":"Git操作手册/3.分支管理/03.分支策略.md","lastUpdated":1783947942000}'),n={name:"git/branch/branch-strategy/index.md"};function d(o,e,p,h,c,u){return t(),s("div",null,[...e[0]||(e[0]=[l(`<h1 id="分支策略" tabindex="-1">分支策略 <a class="header-anchor" href="#分支策略" aria-label="Permalink to &quot;分支策略&quot;">​</a></h1><blockquote><p>不只学会开分支，学会什么时候开、怎么命名、什么时候删</p></blockquote><h2 id="为什么需要策略" tabindex="-1">为什么需要策略 <a class="header-anchor" href="#为什么需要策略" aria-label="Permalink to &quot;为什么需要策略&quot;">​</a></h2><p>前两篇学会了创建、合并、解决冲突。但如果团队没有约定，很快就会变成这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>master</span></span>
<span class="line"><span>feature-login</span></span>
<span class="line"><span>feature-login-new</span></span>
<span class="line"><span>feature-login-final</span></span>
<span class="line"><span>fix-bug</span></span>
<span class="line"><span>fix-bug-urgent</span></span>
<span class="line"><span>test-branch</span></span>
<span class="line"><span>test-branch2</span></span></code></pre></div><p>没有人知道哪个分支在干什么、能不能删、谁在用。<strong>分支策略就是团队之间的约定——分支怎么分、叫什么、什么时候合、什么时候删。</strong></p><h2 id="最简模型-master-feature" tabindex="-1">最简模型：master + feature <a class="header-anchor" href="#最简模型-master-feature" aria-label="Permalink to &quot;最简模型：master + feature&quot;">​</a></h2><p>小团队或个人项目，两个分支就够：</p><p><img src="`+r+'" alt="alt text"></p><p>工作流很简单：要做新功能 → 从 master 开出 feature 分支 → 开发完成合并回 master → 删除 feature 分支。永远保持 master 干净可发布。</p><h2 id="标准模型-引入-develop-分支" tabindex="-1">标准模型：引入 develop 分支 <a class="header-anchor" href="#标准模型-引入-develop-分支" aria-label="Permalink to &quot;标准模型：引入 develop 分支&quot;">​</a></h2><p>团队大了之后，master 只放<strong>稳定发布版本</strong>，日常开发在 <code>develop</code> 上进行：</p><p><img src="'+i+`" alt="alt text"></p><ul><li><strong>master</strong> — 线上代码，只接受来自 develop 或 hotfix 的合并</li><li><strong>develop</strong> — 开发主线，所有 feature 合并到这里</li><li><strong>feature</strong> — 单个功能分支，从 develop 开出，完成后合并回 develop 并删除</li></ul><h2 id="辅助分支-release-和-fixbug" tabindex="-1">辅助分支：release 和 fixbug <a class="header-anchor" href="#辅助分支-release-和-fixbug" aria-label="Permalink to &quot;辅助分支：release 和 fixbug&quot;">​</a></h2><p>发布前需要测试、修小 bug，开一条 <code>release</code> 分支；线上出紧急问题，从 master 开一条 <code>fixbug</code> 分支：</p><table tabindex="0"><thead><tr><th>分支类型</th><th>从哪开出</th><th>合并到哪</th><th>命名示例</th><th>存活时间</th></tr></thead><tbody><tr><td>master</td><td>—</td><td>—</td><td><code>master</code></td><td>永久</td></tr><tr><td>develop</td><td>master</td><td>—</td><td><code>develop</code></td><td>永久</td></tr><tr><td>feature</td><td>develop</td><td>develop</td><td><code>feature-*</code></td><td>功能完成后删除</td></tr><tr><td>release</td><td>develop</td><td>master + develop</td><td><code>release-*</code></td><td>发布后删除</td></tr><tr><td>fixbug</td><td>master</td><td>master + develop</td><td><code>fixbug-*</code></td><td>修复后删除</td></tr></tbody></table><h3 id="release-分支的工作流" tabindex="-1">release 分支的工作流 <a class="header-anchor" href="#release-分支的工作流" aria-label="Permalink to &quot;release 分支的工作流&quot;">​</a></h3><p>准备发版时，从 develop 开出 release 分支，在上面只修 bug、不开发新功能。测试通过后，合并到 master（发布上线）和 develop（同步修复）。</p><h3 id="fixbug-分支的工作流" tabindex="-1">fixbug 分支的工作流 <a class="header-anchor" href="#fixbug-分支的工作流" aria-label="Permalink to &quot;fixbug 分支的工作流&quot;">​</a></h3><p>线上出紧急问题，从 master 开出 fixbug 分支，修完合并回 master（紧急发布）和 develop（同步修复），然后删除。</p><h2 id="分支命名约定" tabindex="-1">分支命名约定 <a class="header-anchor" href="#分支命名约定" aria-label="Permalink to &quot;分支命名约定&quot;">​</a></h2><p>团队统一命名规则，一看就知道是干什么的：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">feature-login</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 开发登录功能</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">feature-payment</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 开发支付模块</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">release-2.1.0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 2.1.0 版本发布准备</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fixbug-login-crash</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 修复登录崩溃问题</span></span></code></pre></div><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>分支策略不用死记，记住核心原则：</p><ol><li><strong>master 永远可发布</strong> — 不直接在 master 上开发</li><li><strong>功能开发走 feature</strong> — 从 develop 开出，完成合回、删除</li><li><strong>紧急修复走 fixbug</strong> — 从 master 开出，修完同时合并到 master 和 develop</li><li><strong>发布前走 release</strong> — 冻结功能、只修 bug，发布后删除</li></ol><h2 id="自主练习" tabindex="-1">自主练习 <a class="header-anchor" href="#自主练习" aria-label="Permalink to &quot;自主练习&quot;">​</a></h2><ol><li>模拟标准模型：创建 master 和 develop 分支，从 develop 开出一条 feature 分支，提交后合并回 develop</li><li>模拟紧急修复：在 master 上开一条 fixbug 分支，做一次提交，同时合并到 master 和 develop</li><li>尝试删除已合并的分支和未合并的分支，观察 <code>-d</code> 和 <code>-D</code> 的区别</li></ol>`,29)])])}const m=a(n,[["render",d]]);export{b as __pageData,m as default};
